/**
 * The native half of a build: writes the generated C (templates, registry, bundle) and a
 * CMake project that links them with CUI, QuickJS-ng and the runtime, then runs CMake.
 * Generated files are only rewritten when their content changes, so CMake rebuilds what moved.
 */
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join, basename, resolve } from 'node:path';
import { createHash } from 'node:crypto';
import { PKG_ROOT, type ComponentOutput } from './bundle.ts';

/**
 * Where CUI's sources are: CUISV_CUI_ROOT, a copy shipped inside the package (cui/, made
 * by scripts/pack.ts), the CUI checkout this package lives in, or the app's package.json
 * ("cui-svelte": { "cui_root": "…" }, which `cui-svelte create` writes for local installs).
 */
function find_cui_root(): string {
	const has = (d: string) => existsSync(join(d, 'include', 'cui', 'cui.h'));
	const candidates = [process.env.CUISV_CUI_ROOT, join(PKG_ROOT, 'cui'), join(PKG_ROOT, '..')];
	for (let d = process.cwd(); ; d = join(d, '..')) {
		const pkg = join(d, 'package.json');
		if (existsSync(pkg)) {
			try {
				const root = JSON.parse(readFileSync(pkg, 'utf8'))['cui-svelte']?.cui_root;
				if (root) candidates.push(resolve(d, root));
			} catch {
				/* not ours */
			}
		}
		if (join(d, '..') === d) break;
	}
	return candidates.find((d): d is string => !!d && has(d)) ?? join(PKG_ROOT, '..');
}

export const CUI_ROOT = find_cui_root();

export interface NativeOptions {
	/** .cui-svelte/<mode> */
	dir: string;
	name: string;
	release: boolean;
	/** Embed the bundle (release) or load it from CUISV_BUNDLE (dev). */
	embed: boolean;
	/** Build the headless test host instead of the windowed app. */
	test?: boolean;
	verbose?: boolean;
}

function write_if_changed(file: string, content: string | Uint8Array): boolean {
	if (existsSync(file)) {
		const old = readFileSync(file);
		const next = typeof content === 'string' ? Buffer.from(content) : Buffer.from(content);
		if (old.equals(next)) return false;
	}
	writeFileSync(file, content);
	return true;
}

function cmake_path(p: string) {
	return p.split('\\').join('/');
}

/** The C files of every component, the registry, and the bundle. */
export function write_sources(opts: NativeOptions, components: Map<string, ComponentOutput>, js: string): { changed: boolean } {
	const gen = join(opts.dir, 'gen');
	mkdirSync(gen, { recursive: true });
	let changed = false;
	const wanted = new Set<string>();
	const symbols: string[] = [];
	const natives: string[] = [];
	const sorted = [...components.values()].sort((a, b) => a.key.localeCompare(b.key));
	for (const c of sorted) {
		const file = 'c_' + c.key.replace(/[^A-Za-z0-9]+/g, '_') + '.c';
		wanted.add(file);
		changed = write_if_changed(join(gen, file), c.result.c) || changed;
		for (const t of c.result.templates) symbols.push(t.symbol);
		if (c.result.natives) natives.push(c.result.natives);
	}
	const registry = [
		'/* Generated by cui-svelte: every template of the app. Do not edit. */',
		'#include "cuisv.h"',
		...symbols.map((s) => `extern const cuisv_template ${s};`),
		`const cuisv_template *const cuisv_templates[] = { ${symbols.map((s) => '&' + s).join(', ') || 'NULL'} };`,
		`const int cuisv_template_count = ${symbols.length};`,
		...natives.map((n) => `extern const cuisv_native ${n}[]; extern const int ${n}_count;`),
		`const cuisv_native *const cuisv_native_tables[] = { ${natives.join(', ') || 'NULL'} };`,
		`const int *const cuisv_native_table_counts[] = { ${natives.map((n) => '&' + n + '_count').join(', ') || 'NULL'} };`,
		`const int cuisv_native_table_count = ${natives.length};`,
		''
	].join('\n');
	wanted.add('registry.c');
	changed = write_if_changed(join(gen, 'registry.c'), registry) || changed;
	wanted.add('bundle.c');
	changed = write_if_changed(join(gen, 'bundle.c'), bundle_c(opts.embed ? js : '')) || changed;
	for (const f of readdirSync(gen)) {
		if (!wanted.has(f)) {
			rmSync(join(gen, f));
			changed = true;
		}
	}
	write_cmake(opts);
	return { changed };
}

function bundle_c(js: string): string {
	const bytes = Buffer.from(js, 'utf8');
	const lines: string[] = [];
	for (let i = 0; i < bytes.length; i += 24) {
		lines.push('    ' + Array.from(bytes.subarray(i, i + 24), (b) => '0x' + b.toString(16).padStart(2, '0')).join(','));
	}
	return [
		'/* Generated by cui-svelte: the app\'s JS bundle. Do not edit. */',
		'#include <stddef.h>',
		`const unsigned char cuisv_bundle[] = {\n${lines.join(',\n') || '    0'}\n};`,
		`const size_t cuisv_bundle_size = ${bytes.length};`,
		'const int cuisv_bundle_bytecode = 0;',
		''
	].join('\n');
}

/**
 * Apps build inside one CMake tree per configuration, shared by every app on the machine
 * (in the user's cache folder), so CUI and QuickJS compile once; an app's own folder holds
 * only its generated sources and a CMakeLists.txt with its targets.
 */
export function cache_root(): string {
	if (process.env.CUISV_CACHE) return process.env.CUISV_CACHE;
	const home = process.env.HOME ?? process.env.USERPROFILE ?? '.';
	const base =
		process.platform === 'win32'
			? (process.env.LOCALAPPDATA ?? join(home, 'AppData', 'Local'))
			: process.platform === 'darwin'
				? join(home, 'Library', 'Caches')
				: (process.env.XDG_CACHE_HOME ?? join(home, '.cache'));
	return join(base, 'cui-svelte', createHash('sha1').update(PKG_ROOT).digest('hex').slice(0, 10));
}

function target_name(opts: NativeOptions) {
	return `app_${createHash('sha1').update(opts.dir).digest('hex').slice(0, 8)}`;
}

function write_cmake(opts: NativeOptions) {
	const rt = cmake_path(join(PKG_ROOT, 'runtime'));
	const cui = cmake_path(CUI_ROOT);
	const tgt = target_name(opts);
	const cmake = `# Generated by cui-svelte. Do not edit. Built from the shared tree in ${cmake_path(cache_root())}.
file(GLOB CUISV_GEN "\${CMAKE_CURRENT_SOURCE_DIR}/gen/*.c")
foreach(variant app test)
    if(variant STREQUAL "app")
        set(t ${tgt})
        set(main cuisv_main.c)
        set(out ${opts.name})
    else()
        set(t ${tgt}_test)
        set(main cuisv_test_main.c)
        set(out ${opts.name}_test)
    endif()
    add_executable(\${t} WIN32 "${rt}/\${main}" \${CUISV_GEN})
    set_target_properties(\${t} PROPERTIES OUTPUT_NAME \${out} RUNTIME_OUTPUT_DIRECTORY "\${CMAKE_CURRENT_SOURCE_DIR}/bin"
        RUNTIME_OUTPUT_DIRECTORY_DEBUG "\${CMAKE_CURRENT_SOURCE_DIR}/bin" RUNTIME_OUTPUT_DIRECTORY_RELEASE "\${CMAKE_CURRENT_SOURCE_DIR}/bin")
    target_include_directories(\${t} PRIVATE "${rt}" "${cui}/src")
    target_link_libraries(\${t} PRIVATE cuisv_runtime cui::cui cuisv_quickjs)
    if(MSVC)
        target_link_options(\${t} PRIVATE /ENTRY:mainCRTStartup)
    else()
        target_compile_options(\${t} PRIVATE -Wall -Wno-unused-parameter -Wno-unused-variable -Wno-unused-but-set-variable -Wno-missing-field-initializers -Wno-unused-function)
    endif()
endforeach()
`;
	write_if_changed(join(opts.dir, 'CMakeLists.txt'), cmake);
}

/** Writes the shared tree; true when its list of apps changed (CMake must configure again). */
function write_workspace(ws: string, app_dir: string): boolean {
	const qjs = cmake_path(join(PKG_ROOT, 'third_party', 'quickjs-ng'));
	const rt = cmake_path(join(PKG_ROOT, 'runtime'));
	const cui = cmake_path(CUI_ROOT);
	mkdirSync(ws, { recursive: true });
	write_if_changed(
		join(ws, 'CMakeLists.txt'),
		`# Generated by cui-svelte: CUI, QuickJS and the runtime, built once for every app.
cmake_minimum_required(VERSION 3.14)
project(cui_svelte_apps C)

set(CUI_BUILD_EXAMPLES OFF CACHE BOOL "" FORCE)
set(CUI_BUILD_TESTS OFF CACHE BOOL "" FORCE)
add_subdirectory("${cui}" cui)

add_library(cuisv_quickjs STATIC "${qjs}/quickjs-amalgam.c")
target_include_directories(cuisv_quickjs PUBLIC "${qjs}")
if(MSVC)
    target_compile_options(cuisv_quickjs PRIVATE /w)
else()
    target_compile_options(cuisv_quickjs PRIVATE -w)
    target_link_libraries(cuisv_quickjs PUBLIC m)
endif()
find_package(Threads)
if(Threads_FOUND)
    target_link_libraries(cuisv_quickjs PUBLIC Threads::Threads)
endif()

add_library(cuisv_runtime STATIC
    "${rt}/cuisv.c" "${rt}/cuisv_js.c" "${rt}/cuisv_app.c" "${rt}/cuisv_cui.c" "${rt}/cuisv_records.c" "${rt}/cuisv_host.c" "${rt}/cuisv_services.c")
target_include_directories(cuisv_runtime PUBLIC "${rt}" PRIVATE "${cui}/src")
target_link_libraries(cuisv_runtime PUBLIC cui::cui cuisv_quickjs)

include("\${CMAKE_CURRENT_SOURCE_DIR}/apps.cmake")
`
	);
	// every app this tree builds; folders that are gone drop out
	const list = join(ws, 'apps.txt');
	const apps = new Set(existsSync(list) ? readFileSync(list, 'utf8').split('\n').filter(Boolean) : []);
	apps.add(app_dir);
	const live = [...apps].filter((d) => existsSync(join(d, 'CMakeLists.txt'))).sort();
	write_if_changed(list, live.join('\n') + '\n');
	return write_if_changed(
		join(ws, 'apps.cmake'),
		live.map((d) => `add_subdirectory("${cmake_path(d)}" "apps/${createHash('sha1').update(d).digest('hex').slice(0, 8)}")`).join('\n') + '\n'
	);
}

export interface BuildOutcome {
	ok: boolean;
	binary: string;
	log: string;
}

function run(cmd: string, args: string[], cwd: string, verbose: boolean): { ok: boolean; log: string } {
	const r = spawnSync(cmd, args, { cwd, encoding: 'utf8', stdio: verbose ? 'inherit' : 'pipe' });
	return { ok: r.status === 0, log: (r.stdout ?? '') + (r.stderr ?? '') };
}

export function cmake_build(opts: NativeOptions): BuildOutcome {
	const type = opts.release ? 'Release' : 'Debug';
	const ws = join(cache_root(), type.toLowerCase());
	const apps_changed = write_workspace(ws, opts.dir);
	const build = join(ws, 'build');
	let log = '';
	// a configure that failed (or never ran) leaves no marker, so it runs again
	const marker = join(build, '.cuisv-configured');
	if (apps_changed || !existsSync(marker)) {
		const c = run('cmake', ['-S', ws, '-B', build, `-DCMAKE_BUILD_TYPE=${type}`], ws, !!opts.verbose);
		log += c.log;
		if (!c.ok) return { ok: false, binary: '', log };
		writeFileSync(marker, '');
	}
	const jobs = String(Math.max(2, globalThis.navigator?.hardwareConcurrency ?? 4));
	const target = target_name(opts) + (opts.test ? '_test' : '');
	const b = run('cmake', ['--build', build, '--config', type, '--parallel', jobs, '--target', target], ws, !!opts.verbose);
	log += b.log;
	const exe = `${opts.name}${opts.test ? '_test' : ''}${process.platform === 'win32' ? '.exe' : ''}`;
	return { ok: b.ok, binary: join(opts.dir, 'bin', exe), log };
}

export function app_name(entry: string): string {
	const base = basename(join(entry, '..'));
	return (base.replace(/[^A-Za-z0-9_]+/g, '_') || 'app').replace(/^(\d)/, '_$1');
}
